#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <sea:bus_read.glsl>
#include <sea:atmosphere.glsl>
#include <sea:fog.glsl>
#include <sea:water.glsl>

// The atmosphere: a scattered sky in place of the vanilla one, with the vanilla moon and stars on top,
// and the distance fog of the world and the clouds turned to that sky instead of the flat fog color.
// Water pixels are tagged in alpha for the water pass: 0.5 for a horizontal surface, 0.25 for a side.
uniform sampler2D InSampler;
uniform sampler2D DepthSampler;
uniform sampler2D ExposureSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    ivec2 pixel = ivec2(texCoord * vec2(textureSize(InSampler, 0)));
    vec4 original = texelFetch(InSampler, pixel, 0);

    // Water markers (sea:water.glsl): a marker pixel takes the vanilla water of its neighbours, and both
    // the marker and the pixel to its right are water.
    float waterData = 0.0;
    bool drawn = texelFetch(DepthSampler, pixel, 0).r > 0.0;
    if (drawn && sea_is_water_marker(original, pixel.x)) {
        waterData = original.b;
        vec4 right = texelFetch(InSampler, pixel + ivec2(1, 0), 0);
        vec4 left = texelFetch(InSampler, pixel - ivec2(1, 0), 0);
        bool leftIsWater = sea_is_water_marker(texelFetch(InSampler, pixel - ivec2(2, 0), 0), pixel.x - 2);
        original = leftIsWater ? 0.5 * (left + right) : right;
    } else if ((pixel.x & 1) == 1) {
        vec4 left = texelFetch(InSampler, pixel - ivec2(1, 0), 0);
        if (drawn && sea_is_water_marker(left, pixel.x - 1)) {
            waterData = left.b;
        }
    }

    vec3 color = original.rgb;
    SeaBus bus = sea_read_bus(InSampler);
    bool inAir = bus.present && sea_in_air(bus);

    if (inAir) {
        float exposure = sea_unpack_float(texelFetch(ExposureSampler, ivec2(0, 0), 0));
        float depth = texture(DepthSampler, texCoord).r;
        bool sky = depth <= 0.0;   // reversed depth: nothing drawn here
        vec3 position = bus.viewToWorld * sea_view_position(bus, texCoord, sky ? 1e-6 : depth);   // the sky from the far plane: ProjMat includes the view bobbing, whose translation turned directions read from a near point
        vec3 dir = normalize(position);

        vec3 transmittance;
        vec3 skyLinear = sea_sky(dir, bus.sunDirection, bus.rainBrightness, sea_altitude(float(CameraBlockPos.y) - CameraOffset.y), transmittance);
        vec3 discLinear = sea_sun_disc(dir, bus.sunDirection, transmittance, bus.rainBrightness);
        vec3 skyColor = sea_tonemap(skyLinear * exposure);
        vec3 skyWithSun = sea_tonemap((skyLinear + discLinear) * exposure);

        if (sky) {
            // The frame was cleared to the fog color: whatever is above it is the moon and the stars.
            color = skyWithSun + max(original.rgb - bus.fogColor, 0.0);
        } else {
            float alpha = original.a;
            float cameraY = float(CameraBlockPos.y) - CameraOffset.y;
            if (alpha < 0.99 && position.y + cameraY > SEA_CLOUD_BOTTOM) {
                // Clouds: their alpha is their coverage, faded with distance, and the rest is the clear color
                // showing through. Replace that part with the sky.
                color = original.rgb + (1.0 - alpha) * (skyWithSun - bus.fogColor);
            } else {
                // Terrain, water, entities: vanilla mixed the fog color in by `fog`, and where the surface is
                // translucent with nothing behind it (far water), the clear color shows through by 1 - alpha:
                //     original = alpha * mix(surface, fogColor, fog) + (1 - alpha) * fogColor
                // Take the fog color back out and mix the sky in by `amount` instead, at least as much: more haze
                // with distance (aerial perspective), and a softer fade at the edge of the loaded world.
                float fog = sea_vanilla_fog(bus, position);
                float amount = sea_fog_amount(bus, position, fog);
                vec3 surface = original.rgb - (1.0 - alpha) * bus.fogColor - alpha * fog * bus.fogColor;
                float keep = (1.0 - amount) / max(1.0 - fog, 1e-4);
                color = surface * keep + alpha * amount * skyColor + (1.0 - alpha) * skyWithSun;
            }
        }
    }

    // Paint the bus column over with its neighbour.
    if (pixel.x == 0) {
        color = texelFetch(InSampler, ivec2(1, pixel.y), 0).rgb;
    }
    float tag = !inAir || waterData == 0.0 ? 1.0 : waterData > 0.75 ? 0.5 : 0.25;
    fragColor = vec4(clamp(color, 0.0, 1.0), tag);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    fragColor = vec4(texture(InSampler, texCoord).rgb, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <sea:bus_read.glsl>
#include <sea:atmosphere.glsl>

// Exposure for the sky, into a 1 x 1 target: the average sky luminance over a few directions sets how
// bright the sky is drawn, like a camera's automatic exposure. Bounded, so the night stays dark.
uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    SeaBus bus = sea_read_bus(InSampler);
    float exposure = 1.0;
    if (bus.present) {
        float altitude = sea_altitude(float(CameraBlockPos.y) - CameraOffset.y);
        vec3 sum = vec3(0.0);
        vec3 unused;
        sum += sea_sky(vec3(0.0, 1.0, 0.0), bus.sunDirection, bus.rainBrightness, altitude, unused);
        for (int i = 0; i < 4; i++) {
            float a = float(i) * 0.5 * SEA_PI;
            sum += sea_sky(normalize(vec3(cos(a), 0.25, sin(a))), bus.sunDirection, bus.rainBrightness, altitude, unused);
            sum += sea_sky(normalize(vec3(cos(a), 1.0, sin(a))), bus.sunDirection, bus.rainBrightness, altitude, unused);
        }
        float luminance = dot(sum / 9.0, vec3(0.2126, 0.7152, 0.0722));
        exposure = clamp(SEA_EXPOSURE_KEY / max(luminance, 1e-6), SEA_EXPOSURE_MIN, SEA_EXPOSURE_MAX);
    }
    fragColor = sea_pack_float(exposure);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// Full-screen triangle for post passes, shipped with the pack (vanilla renamed its own in 26.4).
layout(location = 0) out vec2 texCoord;

void main() {
    vec2 uv = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
    gl_Position = vec4(uv * 2.0 - 1.0, 0.0, 1.0);
    texCoord = uv;
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <sea:bus_read.glsl>
#include <sea:atmosphere.glsl>
#include <sea:fog.glsl>

// Water: the surface the atmosphere pass tagged is redrawn with waves, reflections and refraction.
//  - Waves: a sum of directional waves gives the surface's slope at each point (the geometry stays flat).
//  - Reflection: a ray marched in screen space against the depth buffer, else the sky in that direction.
//  - Refraction: the vanilla water (what is underneath, tinted), shifted by the waves.
//  - Fresnel: grazing angles reflect more.
uniform sampler2D InSampler;        // the atmosphere pass's output; alpha tags water (0.5 top, 0.25 side)
uniform sampler2D MainSampler;      // minecraft:main, for the data bus
uniform sampler2D DepthSampler;
uniform sampler2D ExposureSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

#define SEA_SSR_STEPS 40
#define SEA_WAVE_COUNT 8
const float SEA_FRESNEL_WAVES = 0.25;   // how much of the waves' tilt Fresnel sees
const float SEA_REFLECTION_RIPPLE = 0.04;   // how far, in screen units per unit of tilt, the waves shift the mirrored image
const float SEA_WAVE_STRENGTH = 0.6;   // how much the waves tilt the surface
const float SEA_WAVE_FLATTEN_DISTANCE = 48.0;   // the waves tilt half as much this far away
const float SEA_WAVE_GRAZING_STRENGTH = 0.15;   // and this much, at a grazing angle
const vec3 SEA_WATER_ABSORPTION = vec3(0.30, 0.12, 0.08);

// Smooth value noise in [0, 1], for the irregularity of the waves.
float sea_noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = fract(sin(dot(i, vec2(127.1, 311.7))) * 43758.5453);
    float b = fract(sin(dot(i + vec2(1.0, 0.0), vec2(127.1, 311.7))) * 43758.5453);
    float c = fract(sin(dot(i + vec2(0.0, 1.0), vec2(127.1, 311.7))) * 43758.5453);
    float d = fract(sin(dot(i + vec2(1.0, 1.0), vec2(127.1, 311.7))) * 43758.5453);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Height of the surface (blocks), and its gradient, at world position p (x, z) and time t (seconds).
// Deep-water waves: angular frequency sqrt(g k), rounded to a whole number of periods per 1200 s, the
// period of GameTime, so that the waves don't jump when it wraps.
// footprint: the size of a pixel on the surface, in blocks. A wave shorter than a few pixels can't be shown:
// sampled once per pixel, it turns into rings around the camera (moiré). Each wave fades out before that.
// Pure sines repeat: seen from afar, the sea became regular parallel bands. A slow noise bends the wave fronts
// (it shifts the position each wave sees) and varies each wave's amplitude from place to place. The noise
// depends on the position only, so nothing jumps when GameTime wraps; its own slope is left out of the
// gradient, which it barely changes at that scale.
vec3 sea_waves(vec2 p, float t, float footprint) {
    const vec2 directions[SEA_WAVE_COUNT] = vec2[](vec2(1.0, 0.3), vec2(-0.4, 1.0), vec2(0.8, -0.7),
                                                  vec2(-1.0, -0.2), vec2(0.2, -1.0), vec2(0.9, 0.9),
                                                  vec2(-0.7, 0.6), vec2(0.4, 0.95));
    const float wavelengths[SEA_WAVE_COUNT] = float[](7.3, 4.6, 3.1, 2.2, 1.55, 1.1, 0.8, 0.57);
    vec2 warp = (vec2(sea_noise(p * 0.045), sea_noise(p * 0.045 + 31.7)) - 0.5) * 14.0;
    vec3 sum = vec3(0.0);
    for (int i = 0; i < SEA_WAVE_COUNT; i++) {
        vec2 d = normalize(directions[i]);
        float k = 2.0 * SEA_PI / wavelengths[i];
        float omega = round(sqrt(9.81 * k) * 1200.0 / (2.0 * SEA_PI)) * 2.0 * SEA_PI / 1200.0;
        float variation = 0.3 + 1.4 * sea_noise(p * (0.6 / wavelengths[i] / 8.0) + float(i) * 17.3);
        float amplitude = 0.017 * wavelengths[i] * variation * smoothstep(2.0, 6.0, wavelengths[i] / footprint);
        float phase = k * dot(d, p + warp * (0.5 + 0.1 * float(i))) - omega * t;
        sum += amplitude * vec3(sin(phase), k * cos(phase) * d);
    }
    return sum;
}

float sea_fresnel(float cosTheta) {
    return 0.02 + 0.98 * pow(1.0 - clamp(cosTheta, 0.0, 1.0), 5.0);
}

// March the reflected ray in view space; on a hit, where on the screen (xy) and how much to trust it (z).
vec3 sea_screen_space_reflection(SeaBus bus, vec3 origin, vec3 direction) {
    float stepLength = 0.3 + 0.01 * length(origin);
    vec3 previous = origin;
    vec3 position = origin;
    for (int i = 0; i < SEA_SSR_STEPS; i++) {
        position += direction * stepLength;
        vec4 clip = bus.proj * vec4(position, 1.0);
        if (clip.w <= 0.0) {
            break;
        }
        vec2 uv = clip.xy / clip.w * 0.5 + 0.5;
        if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) {
            break;
        }
        float depth = texture(DepthSampler, uv).r;
        if (depth > 0.0) {
            float behind = sea_view_position(bus, uv, depth).z - position.z;   // > 0: the ray went behind the scene
            if (behind > 0.0 && behind < stepLength * 3.0 + 0.5) {
                // Refine between the last two points.
                vec3 a = previous;
                vec3 b = position;
                for (int j = 0; j < 5; j++) {
                    vec3 m = 0.5 * (a + b);
                    vec4 c = bus.proj * vec4(m, 1.0);
                    vec2 muv = c.xy / c.w * 0.5 + 0.5;
                    float md = texture(DepthSampler, muv).r;
                    if (md > 0.0 && sea_view_position(bus, muv, md).z > m.z) {
                        b = m;
                        uv = muv;
                    } else {
                        a = m;
                    }
                }
                vec2 edge = smoothstep(vec2(0.0), vec2(0.08), min(uv, 1.0 - uv));
                float trust = edge.x * edge.y * (1.0 - float(i) / float(SEA_SSR_STEPS));
                return vec3(uv, trust);
            }
        }
        previous = position;
        stepLength *= 1.12;
    }
    return vec3(0.0);
}

void main() {
    vec4 color = texture(InSampler, texCoord);
    SeaBus bus = sea_read_bus(MainSampler);
    float depth = texture(DepthSampler, texCoord).r;
    vec3 viewPosition = sea_view_position(bus, texCoord, max(depth, 1e-6));
    vec3 position = bus.viewToWorld * viewPosition;
    vec3 faceNormal = normalize(cross(dFdx(position), dFdy(position)));   // derivatives: before any branch
    fragColor = vec4(color.rgb, 1.0);
    if (color.a > 0.9 || !bus.present) {
        return;   // not water, or the atmosphere pass was inactive
    }
    bool top = color.a > 0.375;
    float exposure = sea_unpack_float(texelFetch(ExposureSampler, ivec2(0, 0), 0));
    vec3 cameraPosition = vec3(CameraBlockPos) - CameraOffset;
    vec3 view = normalize(position);
    float dist = length(position);

    // Surface normal: waves on horizontal surfaces.
    if (dot(faceNormal, view) > 0.0) {
        faceNormal = -faceNormal;
    }
    vec3 normal = faceNormal;
    if (top) {
        // A pixel's size on the water: its angular size times the distance, stretched at grazing angles.
        float footprint = dist * 2.0 / (bus.proj[1][1] * ScreenSize.y) / max(abs(view.y), 0.05);
        vec3 wave = sea_waves((position + cameraPosition).xz, GameTime * 1200.0, footprint);
        // At a grazing angle, even a small tilt sends the reflection to the sky: the sea stops mirroring the
        // land behind it. So the waves tilt less the flatter the view, and also with distance.
        float grazing = mix(SEA_WAVE_GRAZING_STRENGTH, 1.0, smoothstep(0.02, 0.25, abs(view.y)));
        float strength = SEA_WAVE_STRENGTH * grazing / (1.0 + dist / SEA_WAVE_FLATTEN_DISTANCE);
        normal = normalize(vec3(-wave.y * strength, 1.0, -wave.z * strength));
        if (faceNormal.y < 0.0) {
            normal.y = -normal.y;   // seen from below
        }
    }

    // Reflection: the screen first, the sky where the ray leaves it.
    vec3 reflected = reflect(view, normal);
    if (top && reflected.y * normal.y < 0.0) {
        reflected.y = -reflected.y;   // a steep wave can't reflect into the water
    }
    float altitude = sea_altitude(cameraPosition.y);
    vec3 transmittance;
    vec3 skyLinear = sea_sky(reflected, bus.sunDirection, bus.rainBrightness, altitude, transmittance);
    // The sun's glint: its disc, and a wider lobe for the small waves the normal can't show.
    float glint = pow(max(dot(reflected, bus.sunDirection), 0.0), 600.0) * 2.0;
    skyLinear += sea_sun_disc(reflected, bus.sunDirection, transmittance, bus.rainBrightness)
               + SEA_SUN_RADIANCE * transmittance * glint * bus.rainBrightness;
    vec3 reflection = sea_tonemap(skyLinear * exposure);
    vec3 viewNormal = mat3(transpose(bus.viewToWorld)) * normal;
    // The screen is searched along the reflection of the flat surface, and the waves only shift where its
    // color is read. Searched along the waves' own reflection, a grazing ray hit the land or missed it
    // depending on the slightest tilt, and the sea stopped mirroring what stands behind it.
    mat3 worldToView = mat3(transpose(bus.viewToWorld));
    vec3 viewFace = worldToView * faceNormal;
    vec3 hit = sea_screen_space_reflection(bus, viewPosition + viewFace * 0.05, worldToView * reflect(view, faceNormal));
    if (hit.z > 0.0) {
        vec2 ripple = (viewNormal.xy - viewFace.xy) * SEA_REFLECTION_RIPPLE;
        vec2 uv = hit.xy + ripple;
        vec4 there = texture(InSampler, uv);
        // Keep the shifted read if it lands on screen and not on the water itself.
        vec3 mirrored = there.a > 0.9 && all(greaterThan(uv, vec2(0.0))) && all(lessThan(uv, vec2(1.0)))
                      ? there.rgb : texture(InSampler, hit.xy).rgb;
        reflection = mix(reflection, mirrored, hit.z);
    }

    // Distance fog on the reflection, as on everything else (the refraction already has it).
    vec3 unused;
    vec3 skyAlongView = sea_tonemap(sea_sky(view, bus.sunDirection, bus.rainBrightness, altitude, unused) * exposure);
    float fogAmount = sea_fog_amount(bus, position, sea_vanilla_fog(bus, position));
    reflection = mix(reflection, skyAlongView, fogAmount);

    // Refraction: the vanilla water, shifted by the waves, if the shifted pixel is still water.
    vec2 shifted = texCoord + (viewNormal.xy - (mat3(transpose(bus.viewToWorld)) * faceNormal).xy) * 0.03;
    vec4 under = texture(InSampler, shifted);
    vec3 refraction = under.a < 0.9 ? under.rgb : color.rgb;
    // Absorption: the seabed's depth is unknown (water writes its own depth), but at grazing angles light
    // crosses more water, so the refraction darkens toward blue-green with the angle. Not the part that is
    // already fog.
    float path = 1.0 / max(dot(-view, faceNormal), 0.15);
    refraction = mix(refraction * exp(-SEA_WATER_ABSORPTION * path), refraction, fogAmount);

    // At a grazing angle, Fresnel swings from 0.8 to 0.3 with a slight tilt: with the waves' full normal, the
    // reflection gave way to the water's blue. The waves only take part in it a little.
    float fresnel = sea_fresnel(dot(-view, normalize(mix(faceNormal, normal, SEA_FRESNEL_WAVES))));
    fragColor = vec4(mix(refraction, reflection, fresnel), 1.0);
}

#ifndef SEA_ATMOSPHERE_GLSL
#define SEA_ATMOSPHERE_GLSL

// Sky from single scattering in an Earth-like atmosphere: Rayleigh scattering (air molecules, the blue
// sky), Mie scattering (aerosols, the glow around the sun) and ozone absorption (the deep blue of
// twilight). Ray-marched per pixel, in meters, with the planet's center below the camera.
// Coefficients: Bruneton & Neyret 2008, Hillaire 2020.

#define SEA_VIEW_STEPS 16
#define SEA_LIGHT_STEPS 4

const float SEA_PI = 3.14159265;
const float SEA_PLANET_RADIUS = 6360e3;
const float SEA_ATMOSPHERE_RADIUS = 6460e3;
const vec3 SEA_RAYLEIGH_SCATTERING = vec3(5.802e-6, 13.558e-6, 33.1e-6);
const float SEA_MIE_SCATTERING = 3.996e-6;
const float SEA_MIE_EXTINCTION = 4.440e-6;
const float SEA_MIE_G = 0.8;
const vec3 SEA_OZONE_ABSORPTION = vec3(0.650e-6, 1.881e-6, 0.085e-6);

const vec3 SEA_SUN_RADIANCE = vec3(20.0);
const vec3 SEA_MOON_RADIANCE = vec3(0.020, 0.024, 0.032);   // dimmer and slightly blue: night vision
const vec3 SEA_NIGHT_GLOW = vec3(0.0006, 0.0008, 0.0016);   // airglow and starlight, so night is never black
// Automatic exposure (post/exposure): exposure = key / average sky luminance, within these bounds.
const float SEA_EXPOSURE_KEY = 0.28;
const float SEA_EXPOSURE_MIN = 0.05;
const float SEA_EXPOSURE_MAX = 30.0;
// Distance, in blocks, over which the haze of the air covers about 63% of what is behind it.
const float SEA_HAZE_DISTANCE = 900.0;

// Translucent pixels above this height are clouds (the overworld's cloud_height is 192.33).
const float SEA_CLOUD_BOTTOM = 190.0;

const float SEA_SUN_COS_RADIUS = 0.99985;                    // about 1 degree: bigger than the real sun, reads better

// Density of air, aerosols and ozone at height h, relative to sea level.
vec3 sea_density(float h) {
    return vec3(exp(-h / 8000.0), exp(-h / 1200.0), max(0.0, 1.0 - abs(h - 25000.0) / 15000.0));
}

vec3 sea_extinction(vec3 opticalDepth) {
    return SEA_RAYLEIGH_SCATTERING * opticalDepth.x + SEA_MIE_EXTINCTION * opticalDepth.y + SEA_OZONE_ABSORPTION * opticalDepth.z;
}

// Distance from o (inside the sphere) to where the ray leaves the sphere of radius r centered on the origin.
float sea_sphere_exit(vec3 o, vec3 d, float r) {
    float b = dot(o, d);
    float c = dot(o, o) - r * r;
    return -b + sqrt(max(b * b - c, 0.0));
}

// Distance to where the ray enters the sphere from outside, or -1.
float sea_sphere_entry(vec3 o, vec3 d, float r) {
    float b = dot(o, d);
    float c = dot(o, o) - r * r;
    float h = b * b - c;
    if (h < 0.0) {
        return -1.0;
    }
    return -b - sqrt(h);
}

// Fraction of light that reaches p from direction l, through the rest of the atmosphere.
vec3 sea_transmittance_to_light(vec3 p, vec3 l) {
    if (sea_sphere_entry(p, l, SEA_PLANET_RADIUS) > 0.0) {
        return vec3(0.0);   // behind the planet
    }
    float dt = sea_sphere_exit(p, l, SEA_ATMOSPHERE_RADIUS) / float(SEA_LIGHT_STEPS);
    vec3 depth = vec3(0.0);
    for (int i = 0; i < SEA_LIGHT_STEPS; i++) {
        depth += sea_density(length(p + l * ((float(i) + 0.5) * dt)) - SEA_PLANET_RADIUS) * dt;
    }
    return exp(-sea_extinction(depth));
}

// Light scattered toward the camera along direction d, from a light in direction l with radiance 1.
// transmittance: how much of what is behind the atmosphere along d gets through (for the sun disc).
vec3 sea_scattering(vec3 d, vec3 l, float altitude, out vec3 transmittance) {
    vec3 o = vec3(0.0, SEA_PLANET_RADIUS + altitude, 0.0);
    float rayLength = sea_sphere_exit(o, d, SEA_ATMOSPHERE_RADIUS);
    float mu = dot(d, l);
    float phaseRayleigh = 3.0 / (16.0 * SEA_PI) * (1.0 + mu * mu);
    float g2 = SEA_MIE_G * SEA_MIE_G;
    float phaseMie = 3.0 / (8.0 * SEA_PI) * (1.0 - g2) * (1.0 + mu * mu)
                   / ((2.0 + g2) * pow(1.0 + g2 - 2.0 * SEA_MIE_G * mu, 1.5));
    vec3 depth = vec3(0.0);
    vec3 sum = vec3(0.0);
    // Steps grow quadratically: dense air near the camera gets most of them.
    for (int i = 0; i < SEA_VIEW_STEPS; i++) {
        float t0 = rayLength * pow(float(i) / float(SEA_VIEW_STEPS), 2.0);
        float t1 = rayLength * pow(float(i + 1) / float(SEA_VIEW_STEPS), 2.0);
        float dt = t1 - t0;
        vec3 p = o + d * (0.5 * (t0 + t1));
        vec3 density = sea_density(length(p) - SEA_PLANET_RADIUS);
        vec3 toCamera = exp(-sea_extinction(depth + density * (0.5 * dt)));
        vec3 scatter = SEA_RAYLEIGH_SCATTERING * density.x * phaseRayleigh + SEA_MIE_SCATTERING * density.y * phaseMie;
        sum += toCamera * sea_transmittance_to_light(p, l) * scatter * dt;
        depth += density * dt;
    }
    transmittance = exp(-sea_extinction(depth));
    return sum;
}

// Linear radiance of the sky in world direction dir, without the sun disc. The ground below the horizon
// is not modeled: directions below it look at the horizon, darkened.
vec3 sea_sky(vec3 dir, vec3 sunDirection, float rainBrightness, float altitude, out vec3 transmittance) {
    vec3 d = normalize(vec3(dir.x, max(dir.y, 0.0), dir.z));
    vec3 color = SEA_NIGHT_GLOW;
    transmittance = vec3(1.0);
    if (sunDirection.y > -0.3) {
        color += sea_scattering(d, sunDirection, altitude, transmittance) * SEA_SUN_RADIANCE;
    }
    if (-sunDirection.y > -0.3) {
        vec3 unused;
        color += sea_scattering(d, -sunDirection, altitude, unused) * SEA_MOON_RADIANCE;
    }
    color *= mix(1.0, 0.25, smoothstep(0.0, -0.3, dir.y));
    // Rain: a grey, darker overcast sky.
    float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
    return mix(color, vec3(luminance * 0.45), (1.0 - rainBrightness) * 0.9);
}

// Linear radiance of the sun disc in direction dir, seen through the atmosphere.
vec3 sea_sun_disc(vec3 dir, vec3 sunDirection, vec3 transmittance, float rainBrightness) {
    float c = dot(dir, sunDirection);
    if (c < SEA_SUN_COS_RADIUS - 0.0001 || dir.y < 0.0) {
        return vec3(0.0);
    }
    float edge = smoothstep(SEA_SUN_COS_RADIUS - 0.0001, SEA_SUN_COS_RADIUS + 0.00002, c);
    // Limb darkening: the edge of the disc is dimmer than its center.
    float r = sqrt(clamp((1.0 - c) / (1.0 - SEA_SUN_COS_RADIUS), 0.0, 1.0));
    float limb = 0.4 + 0.6 * sqrt(1.0 - r * r);
    return SEA_SUN_RADIANCE * 40.0 * transmittance * edge * limb * rainBrightness * rainBrightness;
}

// Height of the camera above the sea, in meters, from its block height: the overworld sea is at y = 63.
float sea_altitude(float cameraY) {
    return clamp(200.0 + (cameraY - 63.0) * 2.0, 20.0, 4000.0);
}

// ACES filmic curve (Narkowicz 2015), then sRGB-like gamma.
vec3 sea_tonemap(vec3 linear) {
    vec3 x = linear;
    vec3 mapped = clamp(x * (2.51 * x + 0.03) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
    return pow(mapped, vec3(1.0 / 2.2));
}

