#ifndef SEA_FOG_GLSL
#define SEA_FOG_GLSL

#include <sea:bus_read.glsl>
#include <sea:atmosphere.glsl>

// The fog, recomputed in post effects from a pixel's camera-relative position and the fog distances of
// the bus, and the stronger fog the pack uses instead.

float sea_linear_fog(float distance, float start, float end) {
    return clamp((distance - start) / max(end - start, 1e-3), 0.0, 1.0);
}

// How much of the fog color vanilla mixed in at this position (fog.glsl, for terrain and entities).
float sea_vanilla_fog(SeaBus bus, vec3 position) {
    float spherical = length(position);
    float cylindrical = max(length(position.xz), abs(position.y));
    return max(sea_linear_fog(spherical, bus.fogEnvironmentalStart, bus.fogEnvironmentalEnd),
               sea_linear_fog(cylindrical, bus.fogRenderDistanceStart, bus.fogRenderDistanceEnd));
}

// How much of the sky the pack mixes in instead, at least vanilla's: a haze that grows with distance
// (aerial perspective), and a softer fade at the edge of the loaded world.
float sea_fog_amount(SeaBus bus, vec3 position, float vanillaFog) {
    float cylindrical = max(length(position.xz), abs(position.y));
    float edge = smoothstep(0.5, 0.95, cylindrical / bus.fogRenderDistanceEnd);
    float haze = 1.0 - exp(-length(position) / SEA_HAZE_DISTANCE);
    return 1.0 - (1.0 - max(vanillaFog, edge)) * (1.0 - haze);
}

#endif

#ifndef SEA_WATER_GLSL
#define SEA_WATER_GLSL

// Water markers. The terrain shaders (vanilla and Sodium) recognize water fragments, and on every even
// screen column write a marker instead of the water color, with alpha 1 so that blending keeps it exact.
// Odd columns keep the vanilla water, blended over what is underneath: the post effects take the
// refraction color from them, and redraw the surface.
//
// Water textures (water_still, water_flow, water_overlay) have a uniform alpha of 180/255. The slime block
// shares it, but water is tinted by the biome and slime is not.
#define SEA_WATER_ALPHA 180.0

bool sea_is_water(vec4 textureColor, vec4 tint) {
    return abs(textureColor.a * 255.0 - SEA_WATER_ALPHA) < 0.5
        && max(tint.r, max(tint.g, tint.b)) - min(tint.r, min(tint.g, tint.b)) > 0.05;
}

// The marker of column x: two bytes that depend on x, so that a scene color matches by chance with a
// probability of 1 in 65536 per pixel, and only where it is also at the right place. Only x is used:
// gl_FragCoord.y doesn't count from the same edge on every backend. The third byte carries data.
vec4 sea_water_marker(int x, float data) {
    return vec4(float((x * 73 + 11) & 255) / 255.0, float((x * 197 + 89) & 255) / 255.0, data, 1.0);
}

// Two bytes alone are not enough: a uniform color filling whole columns (the clear color under water, where the
// sky isn't drawn) matches the marker of one of the ~850 even columns about once in 77, and that column became a
// vertical stripe. So a marker also has alpha 1 and a valid data byte (0.5 or 1); the caller also checks that
// something was drawn there (depth > 0).
bool sea_is_water_marker(vec4 c, int x) {
    vec4 m = sea_water_marker(x, 0.0);
    bool data = abs(c.b - 1.0) < 0.5 / 255.0 || abs(c.b - 128.0 / 255.0) < 1.0 / 255.0;
    return (x & 1) == 0 && abs(c.r - m.r) < 0.5 / 255.0 && abs(c.g - m.g) < 0.5 / 255.0
        && c.a > 254.5 / 255.0 && data;
}

// The data byte: 1 for a horizontal surface (the top of water, or its bottom seen from below), 0.5 for a side.
float sea_water_data(vec3 cameraRelativePosition) {
    vec3 n = normalize(cross(dFdx(cameraRelativePosition), dFdy(cameraRelativePosition)));
    return abs(n.y) > 0.7 ? 1.0 : 0.5;
}

